	/**  From its `node-role.kubernetes.io/<role>` labels. */
	roles: string[],
	/**  The kubelet's version. */
	version: string,
	os: string,
	arch: string,
	internalIp: string | null,
	/**  Allocatable CPU and memory, as Kubernetes writes them (`4`, `16302048Ki`). */
