/**  One commit, as a sync shows it. */
export type Commit = {
	hash: string,
	shortHash: string,
	subject: string,
	author: string,
	/**  ISO 8601, as the committer's clock wrote it. */
	date: string,
};

export type CommitSpec = {
	/**  The new image's name, `repo[:tag]`; an existing tag moves to it. */
	reference: string,
	/**  The commit message, shown in the image's history. */
	comment: string | null,
	author: string | null,
	/**  Pause the container while committing, so its files are consistent. */
	pause: boolean,
	/**  Dockerfile instructions applied to the image, one per entry, like `ENV MODE=prod`. */
	changes: string[],
};

export type ComposeAction = 
/**
 *  `up -d --remove-orphans`: deploy or redeploy, after pulling the
 *  images the Host lacks through the Engine API. Builds what has no
 *  image yet.
 */
"up" | 
/**
 *  `up -d --remove-orphans --build`: also rebuilds every service with
 *  `build:` first.
 */
"rebuild" | 
/**
 *  Pulls every service's image through the Engine API, then `up` with
 *  what was pulled, so only services whose image changed are recreated.
 *  Stops after a failed pull, leaving the running containers alone.
 */
"update" | 
/**  Pulls every service's image through the Engine API; compose isn't run. */
"pull" | 
/**  `down --remove-orphans`, keeping volumes. */
"down" | 
/**  `down -v --remove-orphans`: also deletes the Stack's volumes. */
"downWithVolumes";

export type ComposeCheck = {
	/**  Problems that block deploying. */
	errors: string[],
	/**  Things that will probably not do what the author expects. */
	warnings: string[],
	/**  The Compose profiles its services declare, sorted. */
	profiles: string[],
};

/**  How to invoke Compose on this machine. */
export type ComposeCli = {
	program: string,
	/**  `["compose"]` for the Docker CLI plugin, empty for standalone `docker-compose`. */
	prefix: string[],
	version: string,
};

export type ComposeEvent = { type: "line"; text: string } | 
/**  `error` explains a failed exit, from the end of stderr. */
{ type: "exit"; success: boolean; code: number | null; error: AppError | null } | { type: "error"; error: AppError };

/**  One compose file of a Managed Stack. */
export type ComposeFile = {
	/**  A file name such as `compose.prod.yaml`, unique in the Stack. */
	name: string,
	content: string,
};

/**  The compose CLI used to deploy Managed Stacks, or why there's none. */
export type ComposeSupport = { state: "available"; cli: ComposeCli } | 
/**  `problem` says what's missing and how to install it. */
{ state: "unavailable"; problem: AppError };

/**  One condition of a resource's status. */
export type ConditionView = {
	type: string,
	/**  `True`, `False` or `Unknown`. */
	status: string,
	reason: string | null,
	message: string | null,
	lastTransition: string | null,
};

/**  A config's content as text, or its size when it isn't text. */
export type ConfigContent = {
	text: string | null,
	size: number,
};

export type ConfigMapDetail = {
	view: ConfigMapView,
	labels: { [key in string]: string },
	annotations: { [key in string]: string },
	values: ConfigValue[],
};

export type ConfigMapView = {
	namespace: string,
	name: string,
	keys: DataKey[],
	created: string | null,
};

/**  A ConfigMap's value; binary ones have none. */
export type ConfigValue = {
	key: string,
	value: string | null,
	size: number,
};

export type Container = {
	id: string,
	name: string,
	image: string,
	imageId: string,
	command: string,
	/**  Unix time in seconds. */
	created: number,
	/**  `created`, `running`, `paused`, `restarting`, `exited`, `removing` or `dead`. */
	state: string,
	/**  Human status from the Engine, e.g. "Up 3 hours (healthy)". */
	status: string,
	health: string | null,
	ports: PortBinding[],
	labels: { [key in string]: string },
	stack: string | null,
	service: string | null,
	networks: string[],
};

export type ContainerAction = "start" | "stop" | "restart" | "pause" | "unpause" | "kill";

export type ContainerUsage = {
	id: string,
	cpuPercent: number | null,
	memoryUsage: number,
	memoryLimit: number,
};

/**  A container and its task, as the list shows them. */
export type ContainerdContainer = {
	id: string,
	/**  nerdctl's name, or the Pod's container's, or the id. */
	name: string,
	image: string,
	labels: { [key in string]: string },
	runtime: string,
	snapshotter: string,
	snapshotKey: string,
	/**  RFC 3339. */
	createdAt: string | null,
	createdBy: CreatedBy,
	/**  The Kubernetes Pod it belongs to, as `namespace/name`. */
	pod: string | null,
	/**  A Pod's pause container, which holds its namespaces. */
	sandbox: boolean,
	state: TaskState,
	/**  The task's main process. */
	pid: number | null,
	/**  How a stopped task ended. */
	exitStatus: number | null,
	exitedAt: string | null,
};

